/** Generated by scaffold-crud-pages. Query hooks for TermExams.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchTermExamsList,
  fetchTermExamsById,
  createTermExams,
  updateTermExams,
  deleteTermExams,
  type FetchTermExamsListParams,
} from '~/services/httpServices/termExamsService';
import type { CreateTermExamsRequest, UpdateTermExamsRequest } from '~/types/term-exams';

const DOMAIN = 'termExams';

export function useTermExamsList(params?: FetchTermExamsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchTermExamsList(params),
  });
}

export function useTermExams(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchTermExamsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateTermExams() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateTermExamsRequest) => createTermExams(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateTermExams() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateTermExamsRequest }) =>
      updateTermExams(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteTermExams() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteTermExams(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
